16 | export function PlayerControls({
17 |   currentTrack,
18 |   currentTrackId,
19 |   isPlaying,
20 |   isShuffled,
21 |   onPlay,
22 |   onPause,
23 |   onNext,
24 |   onPrev,
25 |   onToggleShuffle,
26 |   onToggleFavorite,
27 | }: PlayerControlsProps) {
28 |   return (
29 |     <section className="player-controls">
30 |       <div className="now-playing">
31 |         {currentTrack?.coverUrl && (
32 |           <img
33 |             className="album-art"
34 |             src={currentTrack.coverUrl}
