42 |           {currentTrack?.artist && (
43 |             <span className="track-artist">{currentTrack.artist}</span>
44 |           )}
45 |           {currentTrack?.album && (
46 |             <span className="track-album">{currentTrack.album}</span>
47 |           )}
48 |         </div>
49 |         {currentTrackId && onToggleFavorite && (
50 |           <button
51 |             className={`favorite-btn ${currentTrack?.isFavorite ? "favorite-active" : ""}`}
52 |             onClick={() => onToggleFavorite(currentTrackId)}
53 |             title={currentTrack?.isFavorite ? "Remover dos favoritos" : "Adicionar aos favoritos"}
54 |             aria-label={currentTrack?.isFavorite ? "Remover dos favoritos" : "Adicionar aos favoritos"}
55 |           >
56 |             {currentTrack?.isFavorite ? "♥" : "♡"}
57 |           </button>
58 |         )}
59 |       </div>
60 | 
61 |       <div className="controls">
62 |         <button
63 |           className={`ctrl-btn shuffle-btn ${isShuffled ? "active" : ""}`}
64 |           onClick={onToggleShuffle}
65 |           title={isShuffled ? "Aleatório: ativado" : "Aleatório: desativado"}
66 |         >
67 |           🔀 {isShuffled ? "ON" : "OFF"}
68 |         </button>
69 |         <button className="ctrl-btn" onClick={onPrev} title="Anterior">
70 |           ⏮
71 |         </button>
72 |         <button
73 |           className="ctrl-btn play-btn"
74 |           onClick={isPlaying ? onPause : onPlay}
75 |           title={isPlaying ? "Pausar" : "Tocar"}
76 |         >
77 |           {isPlaying ? "⏸" : "▶"}
78 |         </button>
79 |         <button className="ctrl-btn" onClick={onNext} title="Próxima">
80 |           ⏭
81 |         </button>
82 |       </div>
83 |     </section>
84 |   );
85 | }
